/**
 * Cloud Optimized GeoTIFF, YAML only (0.9, ml-cnv.2) — browser verification,
 * which is also the demo (examples/verification/cloud-native/cog.html and
 * friends).
 *
 * @remarks
 * Fixtures: synthetic, CC0, generated by scripts/fixtures/cog.py into
 * docs/public/gallery-assets/cloud-native/, served by e2e/server.mjs with
 * HTTP range support (and its /norange/, /nocors/ variants). Runs on every
 * maplibre-gl leg of the CI matrix (4/5/6): the COG plugin's floor is 4.5.
 */
import { test, expect, type Page } from "@playwright/test";
import { PNG } from "pngjs";

/** Fail on page errors and off-origin requests (hermeticity). */
async function guard(page: Page): Promise<string[]> {
  const errors: string[] = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.route("**/*", (route) => {
    const url = route.request().url();
    if (/^https?:\/\/(localhost|127\.0\.0\.1)[:/]/.test(url) || /^(data|blob):/.test(url)) return route.continue();
    errors.push(`external request (suite must stay hermetic): ${url}`);
    return route.abort();
  });
  return errors;
}

/** Every response for a file name: status, and whether a Range was sent. */
function recordRequests(page: Page, name: RegExp) {
  const seen: { url: string; status: number; range: string | undefined }[] = [];
  page.on("response", (r) => {
    if (name.test(r.url())) seen.push({ url: r.url(), status: r.status(), range: r.request().headers()["range"] });
  });
  return seen;
}

/** Wait until the map is idle with every tile of `sources` loaded. */
async function waitForTiles(page: Page, selector: string, sources: string[]) {
  await page.waitForFunction(
    ({ selector, sources }) => {
      const el = document.querySelector(selector) as any;
      const map = el?.getMap?.();
      if (!map || !map.loaded()) return false;
      return sources.every((s: string) => map.getSource(s) && map.isSourceLoaded(s)) && map.areTilesLoaded();
    },
    { selector, sources },
    { timeout: 45_000 }
  );
}

/** The pixel at a geographic point of a map element, read from a screenshot. */
async function pixelAt(page: Page, selector: string, lngLat: [number, number]): Promise<[number, number, number]> {
  const at = await page.evaluate(
    ({ selector, lngLat }) => {
      const map = (document.querySelector(selector) as any).getMap();
      const p = map.project(lngLat);
      const rect = map.getCanvas().getBoundingClientRect();
      return { x: Math.round(rect.left + p.x), y: Math.round(rect.top + p.y) };
    },
    { selector, lngLat }
  );
  const shot = PNG.sync.read(await page.screenshot({ clip: { x: at.x, y: at.y, width: 1, height: 1 } }));
  return [shot.data[0]!, shot.data[1]!, shot.data[2]!];
}

/** The local basemap's background (#cfe8c9): what an empty spot of the map shows. */
const BACKGROUND: [number, number, number] = [0xcf, 0xe8, 0xc9];
const distance = (a: number[], b: number[]) => a.reduce((sum, v, i) => sum + Math.abs(v - b[i]!), 0);

test.describe("COG with no page JavaScript", () => {
  test("RGB imagery, a DEM driving hillshade and 3D terrain, fitTo from the file's extent (v1)", async ({ page }) => {
    const errors = await guard(page);
    const cog = recordRequests(page, /^http:\/\/localhost:\d+\/gallery-assets\/cloud-native\/(imagery|elevation)\.cog\.tif$/);
    await page.goto("/examples/verification/cloud-native/cog.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("v1") as any).mapReady());
    await waitForTiles(page, "#v1", ["imagery", "elevation"]);

    const state = await page.evaluate(() => {
      const map = (document.getElementById("v1") as any).getMap();
      const style = map.getStyle();
      return {
        imagery: style.sources.imagery,
        elevation: style.sources.elevation,
        terrain: map.getTerrain(),
        hills: Boolean(map.getLayer("hills")),
        center: map.getCenter().toArray(),
        zoom: map.getZoom(),
        notice: document.querySelector("#v1 .ml-map-notice")?.textContent ?? null,
      };
    });
    // The URL reached MapLibre as the plugin reads it, with 256-pixel tiles.
    expect(state.imagery.url).toMatch(/^cog:\/\/http:\/\/localhost:\d+\/gallery-assets\/cloud-native\/imagery\.cog\.tif$/);
    expect(state.imagery.tileSize).toBe(256);
    expect(state.elevation.url).toMatch(/elevation\.cog\.tif#dem$/);
    expect(state.elevation.encoding).toBe("mapbox");
    expect(state.terrain).toEqual({ source: "elevation", exaggeration: 1.5 });
    expect(state.hills).toBe(true);
    // fitTo framed the file's extent (the document said [0, 0] z2).
    expect(Math.abs(state.center[0] - 10.2), JSON.stringify(state.center)).toBeLessThan(0.1);
    expect(Math.abs(state.center[1] - 42.15), JSON.stringify(state.center)).toBeLessThan(0.1);
    expect(state.zoom).toBeGreaterThan(8);
    expect(state.notice).toBeNull();

    // The DEM really is under the camera: elevation varies across the island.
    await page.waitForFunction(
      () => {
        const map = (document.getElementById("v1") as any).getMap();
        const samples = [
          [10.15, 42.17],
          [10.27, 42.12],
          [10.03, 42.02],
        ].map((p) => map.queryTerrainElevation?.(p));
        if (!samples.every((e: unknown) => typeof e === "number")) return false;
        return Math.max(...samples) - Math.min(...samples) > 300;
      },
      undefined,
      { timeout: 30_000 }
    );

    // The imagery drew: the island isn't the basemap's background.
    const land = await pixelAt(page, "#v1", [10.2, 42.15]);
    expect(distance(land, BACKGROUND), `land pixel ${land}`).toBeGreaterThan(60);

    // Read with range requests only (206), never whole.
    expect(cog.length).toBeGreaterThan(0);
    for (const r of cog) {
      expect(r.range, r.url).toBeTruthy();
      expect(r.status, r.url).toBe(206);
    }
    await page.screenshot({ path: "e2e/results/cog_v1.png" });
    expect(errors).toEqual([]);
  });

  test("one band coloured by colorRamp; no-data stays clear (v2)", async ({ page }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/cog.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("v2") as any).mapReady());
    await waitForTiles(page, "#v2", ["ndvi"]);
    const url = await page.evaluate(() => (document.getElementById("v2") as any).getMap().getStyle().sources.ndvi.url);
    expect(url).toMatch(/ndvi\.cog\.tif#color:\["#ff0000","#0000ff"\],-0\.1,0\.85,c$/);
    await page.waitForTimeout(300);
    // Island: a red–blue mix (the ramp), nothing green.
    const land = await pixelAt(page, "#v2", [10.2, 42.15]);
    expect(land[1], `land pixel ${land}`).toBeLessThan(40);
    expect(land[0] + land[2], `land pixel ${land}`).toBeGreaterThan(150);
    // Sea: no value (NaN), so the basemap shows through.
    const sea = await pixelAt(page, "#v2", [10.03, 42.08]);
    expect(distance(sea, BACKGROUND), `sea pixel ${sea}`).toBeLessThan(12);
    await expect(page.locator("#v2 .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/cog_v2_ramp.png" });
    expect(errors).toEqual([]);
  });

  test("every failure is said in plain words; a plain GeoTIFF draws with a hint", async ({ page }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/cog.html", { waitUntil: "domcontentloaded" });
    for (const id of ["cog-errors", "cog-hint"]) {
      await page.evaluate((id) => (document.getElementById(id) as any).mapReady(), id);
    }
    const notice = page.locator("#cog-errors .ml-map-notice");
    await expect(notice).toContainText(
      "Source latlon didn't load: /gallery-assets/cloud-native/imagery-4326.cog.tif is in EPSG:4326; a COG must be " +
        "in Web Mercator (EPSG:3857) to be drawn. Reproject it: gdalwarp -t_srs EPSG:3857 -of COG -co " +
        "COMPRESS=DEFLATE imagery-4326.cog.tif out.tif (GDAL 3.1 or later)."
    );
    await expect(notice).toContainText(
      "Source norange didn't load: /norange/gallery-assets/cloud-native/imagery.cog.tif was served without " +
        "range-request support (the server sent the whole file instead of the part asked for)."
    );
    await expect(notice).toContainText(
      /Source blocked didn't load: The browser couldn't read http:\/\/127\.0\.0\.1:\d+\/nocors\/gallery-assets\/cloud-native\/imagery\.cog\.tif: the server didn't allow this page to load it \(CORS\)/
    );
    await expect(notice).toContainText(
      "Source webpage didn't load: /gallery-assets/cloud-native/not-really.tif isn't a Cloud Optimized GeoTIFF " +
        "(COG) file. A wrong path often returns a web page instead — check the file name and folder."
    );
    await expect(notice).toContainText(
      "Source missing didn't load: /gallery-assets/cloud-native/missing.tif didn't load (404 Not Found)."
    );
    const text = (await notice.textContent()) ?? "";
    expect(text).not.toMatch(/responded with full file|Failed to fetch|Error fetching data|not supported\. Reproject|Invalid byte order/i);

    // Not cloud-optimized: it draws, and the author is told how to fix it.
    await waitForTiles(page, "#cog-hint", ["plain"]);
    const hint = page.locator("#cog-hint .ml-map-notice");
    await expect(hint).toContainText(
      "/gallery-assets/cloud-native/imagery-plain.tif is a GeoTIFF but not a Cloud Optimized one"
    );
    await expect(hint).toContainText("gdal_translate -of COG -co COMPRESS=DEFLATE imagery-plain.tif out.tif");
    const land = await pixelAt(page, "#cog-hint", [10.2, 42.15]);
    expect(distance(land, BACKGROUND), `plain GeoTIFF pixel ${land}`).toBeGreaterThan(60);
    await page.screenshot({ path: "e2e/results/cog_errors.png", fullPage: true });
    expect(errors).toEqual([]);
  });

  test("on a project site, base applies to a .tif and to the file inside cog://", async ({ page }) => {
    const errors = await guard(page);
    const notFound: string[] = [];
    page.on("response", (r) => {
      if (r.status() === 404) notFound.push(new URL(r.url()).pathname);
    });
    await page.goto("/my-repo/blog/cog.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("with-base") as any).mapReady());
    await waitForTiles(page, "#with-base", ["imagery", "elevation"]);
    const spec = await page.evaluate(() => (document.getElementById("with-base") as any).getMap().getStyle().sources);
    expect(spec.imagery.url).toMatch(/^cog:\/\/http:\/\/localhost:\d+\/my-repo\/cloud-native\/imagery\.cog\.tif$/);
    expect(spec.elevation.url).toMatch(/^cog:\/\/http:\/\/localhost:\d+\/my-repo\/cloud-native\/elevation\.cog\.tif#dem$/);
    await expect(page.locator("#with-base .ml-map-notice")).toHaveCount(0);
    // Without base the same document can't find its files — and says where to look.
    const noBase = page.locator("#no-base .ml-map-notice");
    await expect(noBase).toContainText(
      "Source elevation didn't load: /cloud-native/elevation.cog.tif didn't load (404 Not Found)."
    );
    await expect(noBase).toContainText('add base="/my-repo/" to <ml-map>');
    expect(notFound.filter((p) => p.startsWith("/my-repo/cloud-native/"))).toEqual([]);
    await page.screenshot({ path: "e2e/results/cog_base_path.png" });
    expect(errors).toEqual([]);
  });

  test("<ml-scrollytelling> reads a COG too", async ({ page }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/cog-story.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("story") as any).mapReady());
    await waitForTiles(page, "#story ml-map", ["imagery", "elevation"]);
    const state = await page.evaluate(() => {
      const map = (document.querySelector("#story ml-map") as any).getMap();
      return { url: map.getStyle().sources.imagery.url, hills: Boolean(map.getLayer("hills")) };
    });
    expect(state.url).toMatch(/^cog:\/\/http:\/\/localhost:\d+\/gallery-assets\/cloud-native\/imagery\.cog\.tif$/);
    expect(state.hills).toBe(true);
    const land = await pixelAt(page, "#story ml-map", [10.2, 42.15]);
    expect(distance(land, BACKGROUND), `land pixel ${land}`).toBeGreaterThan(60);
    await expect(page.locator("#story .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/cog_story.png" });
    expect(errors).toEqual([]);
  });

  test("plain HTML from the CDN build: only maplibre-gl in the import map, the COG reader on demand", async ({ page }) => {
    const errors = await guard(page);
    const scripts: string[] = [];
    page.on("request", (r) => {
      if (/\.m?js(\?|$)/.test(r.url())) scripts.push(new URL(r.url()).pathname);
    });
    await page.goto("/examples/verification/cloud-native/cdn-cog.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    await waitForTiles(page, "#map", ["imagery", "elevation"]);
    const land = await pixelAt(page, "#map", [10.2, 42.15]);
    expect(distance(land, BACKGROUND), `land pixel ${land}`).toBeGreaterThan(60);
    await expect(page.locator("#map .ml-map-notice")).toHaveCount(0);
    // The bundle, and the one reader this document needs, from dist/chunks/.
    expect([...new Set(scripts.filter((p) => p.startsWith("/cdn/")))].sort()).toEqual([
      "/cdn/@maplibre-yaml/core@0.9.0/dist/chunks/cog.js",
      "/cdn/@maplibre-yaml/core@0.9.0/dist/register.browser.js",
      "/cdn/@maplibre-yaml/core@0.9.0/register.js",
    ]);
    await page.screenshot({ path: "e2e/results/cog_cdn.png" });
    expect(errors).toEqual([]);
  });

  test("a COG reader the browser couldn't download: a plain notice on the COG sources only", async ({ page }) => {
    const errors = await guard(page);
    await page.route("**/chunks/cog.js", (route) => route.abort("blockedbyclient"));
    await page.goto("/examples/verification/cloud-native/cdn-cog.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    const notice = page.locator("#map .ml-map-notice");
    await expect(notice).toContainText(
      /Source imagery didn't load: The Cloud Optimized GeoTIFF \(COG\) reader \(.*chunks\/cog\.js\) couldn't be downloaded/,
      { timeout: 30_000 }
    );
    await expect(notice).toContainText("Source elevation didn't load");
    expect(errors).toEqual([]);
  });

  test("a strict CSP that refuses blob: workers gets a plain notice, not a silent blank (maplibre-gl 6)", async ({
    page,
  }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/cog-csp.html", { waitUntil: "domcontentloaded" });
    const major = await page.evaluate(async () => {
      const gl = (await import("/vendor/maplibre-gl.esm.js" as string)).default as any;
      return Number(String(gl.getVersion?.() ?? gl.version ?? "0").split(".")[0]);
    });
    // maplibre-gl 4 and 5 start their own workers from blob: too: under this
    // policy no map draws at all, which is MapLibre's own (documented) case.
    test.skip(major < 6, `maplibre-gl ${major} needs blob: workers itself`);
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    await expect(page.locator("#map .ml-map-notice")).toContainText(
      "Source imagery didn't load: The Cloud Optimized GeoTIFF (COG) reader couldn't be set up (this page's " +
        "Content Security Policy doesn't allow the background workers COG images are decoded in; allow them " +
        "with worker-src 'self' blob:), so /gallery-assets/cloud-native/imagery.cog.tif wasn't read."
    );
    expect(errors).toEqual([]);
  });
});
